descriptor.controllerScript:
// ============================================================
// REGISTRO DE CAMBIOS (lo lee el widget de Auditoría)
// Cada vez que este widget cambia un valor, guarda en la entidad una
// telemetría "registro_cambio" con quién lo cambió, el valor ANTERIOR y el
// NUEVO. La Auditoría lee solo esta clave, así que no le afectan los
// recálculos internos (volumen, media proyectada, reescritura del día...).
// ============================================================
var CLAVE_REGISTRO_CAMBIO = 'registro_cambio';
var ultimoTsRegistro = 0;
function usuarioActual(ctx) {
    var u = (ctx && ctx.currentUser) || {};
    if (u.sub || u.email) return u.sub || u.email;
    try {
        var jwt = localStorage.getItem('jwt_token');
        if (jwt) {
            var b64 = jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
            var datos = JSON.parse(decodeURIComponent(escape(atob(b64))));
            return datos.sub || datos.email || '';
        }
    } catch (e) {}
    return '';
}
// cambios: [{ tipo: 'punto'|'media', clave, ts, anterior, nuevo }]
// Los que no cambian de verdad (anterior === nuevo) se descartan solos.
function registrarCambio(ctx, entityType, entityId, cambios) {
    var reales = (cambios || []).map(function (c) {
        var copia = {};
        for (var k in c) { if (c.hasOwnProperty(k)) copia[k] = c[k]; }
        copia.anterior = (c.anterior === null || c.anterior === undefined || isNaN(parseFloat(c.anterior))) ? null : parseFloat(c.anterior);
        copia.nuevo = parseFloat(c.nuevo);
        return copia;
    }).filter(function (c) {
        return !isNaN(c.nuevo) && c.anterior !== c.nuevo;
    });
    if (!reales.length || !entityId) return;
    var ts = Date.now();
    if (ts <= ultimoTsRegistro) ts = ultimoTsRegistro + 1;   // dos registros seguidos no se pisan
    ultimoTsRegistro = ts;
    var payload = { ts: ts, values: {} };
    payload.values[CLAVE_REGISTRO_CAMBIO] = JSON.stringify({ usuario: usuarioActual(ctx), cambios: reales });
    try {
        ctx.http.post('/api/plugins/telemetry/' + (entityType || 'ASSET') + '/' + entityId + '/timeseries/ANY', payload)
            .subscribe(function () {}, function (err) {
                console.error('[registro_cambio] no se pudo guardar el registro del cambio', err);
            });
    } catch (e) {
        console.error('[registro_cambio] excepción al guardar el registro del cambio', e);
    }
}

function madridOffsetMs(t) {
    function lastSundayUtc1(y, m) {
        var last = new Date(Date.UTC(y, m + 1, 0));
        return Date.UTC(y, m, last.getUTCDate() - last.getUTCDay(), 1, 0, 0);
    }
    var y = new Date(t).getUTCFullYear();
    return (t >= lastSundayUtc1(y, 2) && t < lastSundayUtc1(y, 9)) ? 7200000 : 3600000;
}
function construirPuntosPorDia(start, end, valor) {
    if (start === end) {
        const off = madridOffsetMs(start);
        const dLoc = new Date(start + off);
        return { puntos: [{ ts: start, values: { caudal_manual: valor } }], dias: [dLoc.getUTCDate()] };
    }
    const grupos = [];
    const dias = [];
    let cursor = start;
    while (cursor <= end) {
        const off = madridOffsetMs(cursor);
        const dLoc = new Date(cursor + off);
        dLoc.setUTCHours(0, 0, 0, 0);
        const inicioDiaTs = dLoc.getTime() - off;
        const finDiaTs = inicioDiaTs + 86400000 - 1000;
        const tsInicio = Math.max(start, inicioDiaTs);
        const tsFin = Math.min(end, finDiaTs);
        const puntosDia = [{ ts: tsInicio, values: { caudal_manual: valor } }];
        if (tsFin !== tsInicio) {
            puntosDia.push({ ts: tsFin, values: { caudal_manual: valor } });
        }
        grupos.push(puntosDia);
        dias.push(new Date(tsInicio + off).getUTCDate());
        cursor = inicioDiaTs + 86400000;
    }
    if (grupos.length > 1) {
        grupos.pop();
        dias.pop();
    }
    return { puntos: grupos.flat(), dias: dias };
}
// Lee, ANTES de guardar el caudal manual, la media que tenía cada día
// afectado -- es el "valor anterior" del registro de cambios. Prioridad:
//   1) caudal_medio_diario del grupo ese día
//   2) la media del día del grupo: media_proyectada si es hoy, caudal_fijado si no
//   3) caudal_guarda
// Si la petición falla o tarda más de 8 s, se sigue guardando igual (el
// registro quedará sin valor anterior, pero el guardado no se bloquea).
function leerMediasAnteriores($ctx, assetId, puntos, callback) {
    var dias = {};
    puntos.forEach(function(p) {
        var d = new Date(p.ts);
        var inicio = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
        if (!(inicio in dias) || p.ts < dias[inicio]) dias[inicio] = p.ts;
    });
    var inicios = Object.keys(dias).map(Number).sort(function(a, b) { return a - b; });
    if (!inicios.length) { callback([]); return; }
    var desde = inicios[0];
    var hasta = inicios[inicios.length - 1] + 86400000 - 1;
    var claves = ['caudal_medio_diario', 'media_proyectada', 'caudal_fijado', 'caudal_guarda'];
    var url = '/api/plugins/telemetry/ASSET/' + assetId + '/values/timeseries?keys=' + claves.join(',') +
              '&startTs=' + desde + '&endTs=' + hasta + '&limit=10000&agg=NONE';
    var hecho = false;
    function terminar(data) {
        if (hecho) return;
        hecho = true;
        var hoy = new Date();
        var inicioHoy = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate()).getTime();
        callback(inicios.map(function(inicio) {
            function ultimo(clave) {
                var arr = ((data && data[clave]) || []).filter(function(p) { return p.ts >= inicio && p.ts < inicio + 86400000; });
                if (!arr.length) return null;
                arr.sort(function(a, b) { return a.ts - b.ts; });
                var v = parseFloat(arr[arr.length - 1].value);
                return isNaN(v) ? null : v;
            }
            var orden = ['caudal_medio_diario', inicio === inicioHoy ? 'media_proyectada' : 'caudal_fijado', 'caudal_guarda'];
            for (var i = 0; i < orden.length; i++) {
                var v = ultimo(orden[i]);
                if (v !== null) return { ts: dias[inicio], anterior: v, origen: orden[i] };
            }
            return { ts: dias[inicio], anterior: null, origen: null };
        }));
    }
    setTimeout(function() { terminar(null); }, 8000);
    $ctx.http.get(url).subscribe(terminar, function(err) {
        console.warn('[Guardar Caudal Manual] no se pudo leer la media anterior para el registro de cambios:', err);
        terminar(null);
    });
}
// NUEVO: control de la peticion HTTP del valor real de "caudal_manual" del
// dia que se esta viendo -- evita relanzar la peticion cada segundo (el key
// de referencia es realtime) y descarta respuestas viejas si llegan
// DESPUES que una mas nueva (si no, pisaban el valor bueno con uno vacio).
var ultimoDiaPedido = null;
var peticionActual = 0;
var handlerCorreccionGuardadaInput = null; // aviso de correccion de signo (dias anteriores)
self.onInit = function() {
    const $ctx = self.ctx;
    const $container = $ctx.$container;
    setTimeout(function() {
        const assetId = localStorage.getItem('riego_asset_id');
        const currentCaudal = localStorage.getItem('riego_caudal');
        if (currentCaudal && currentCaudal !== "null" && currentCaudal !== "") {
            $container.find('#input-caudal').val(currentCaudal);
        }
        $container.find('#btn-guardar').off('click').on('click', function() {
            const newVal = $container.find('#input-caudal').val();
            const $msg = $container.find('#msg-estado');
            if (!assetId || assetId === "null") {
                $msg.text("⚠ Selecciona una entidad.").css('color', '#d32f2f');
                return;
            }
            if (newVal === "") {
                $msg.text("⚠ Valor vacío.").css('color', '#d32f2f');
                return;
            }
            const tw = $ctx.timeWindow;
            let start, end;
            if (tw && tw.minTime && tw.maxTime) {
                start = tw.minTime;
                end = tw.maxTime - 1000;
            } else {
                start = end = new Date().getTime();
            }
            const valor = parseFloat(newVal);
            $msg.text("Guardando...").css('color', '#1976d2');
            const resultado = construirPuntosPorDia(start, end, valor);
            const puntos = resultado.puntos;
            const diasAfectados = resultado.dias;
            let pendientes = puntos.length;
            let huboError = false;
            // Antes de guardar se lee la media que tenía cada día afectado,
            // para el registro de cambios (Auditoría).
            leerMediasAnteriores($ctx, assetId, puntos, function(anteriores) {
            puntos.forEach(function(payload) {
                $ctx.http.post("/api/plugins/telemetry/ASSET/" + assetId + "/timeseries/ANY", payload).subscribe(
                    function() {
                        pendientes--;
                        if (pendientes === 0) {
                            if (huboError) {
                                $msg.text("Guardado parcial.").css('color', '#f57c00');
                            } else {
                                $msg.text("¡Guardado!").css('color', '#388e3c');
                                localStorage.setItem('riego_caudal', newVal);
                                // Registro para la Auditoría: un cambio por día,
                                // de la media que tenía ese día al caudal manual.
                                registrarCambio($ctx, 'ASSET', assetId, anteriores.map(function(a) {
                                    return { tipo: 'media', clave: 'caudal_manual', ts: a.ts,
                                             anterior: a.anterior, origenAnterior: a.origen, nuevo: valor };
                                }));
                                window.dispatchEvent(new CustomEvent('riego-caudal-manual-guardado', {
                                    detail: { assetId: assetId, valor: valor, dias: diasAfectados }
                                }));
                                // Tras guardar, se vuelve a pedir el valor del dia
                                // que se esta viendo -- por si el guardado afecta
                                // justo al dia mostrado, el campo queda consistente
                                // con lo que hay realmente en el servidor.
                                ultimoDiaPedido = null;
                                cargarCaudalDelDia();
                            }
                            setTimeout(() => $msg.text(""), 3000);
                        }
                    },
                    function(err) {
                        huboError = true;
                        pendientes--;
                        console.error('[Guardar Caudal Manual] Error al guardar:', err);
                        if (pendientes === 0) {
                            $msg.text("Error.").css('color', '#d32f2f');
                        }
                    }
                );
            });
            }); // fin leerMediasAnteriores
        });
        // NUEVO: aviso lanzado por el widget "Comparativa caudales" (dias
        // anteriores) al corregir el signo (+Suma/-Resta) de un caudalimetro
        // para un dia pasado. Este widget vigila el dia mostrado con polling
        // cada 500ms, pero se salta la peticion si ya se pidio ese mismo dia
        // antes ("ultimoDiaPedido"), asi que sin este aviso el campo se
        // quedaba con el valor de antes de corregir para siempre (el
        // polling nunca volvia a preguntar por un dia ya visitado). Si el
        // aviso es para la misma entidad Y el mismo dia que se esta viendo
        // ahora mismo, se resetea esa guarda para que el siguiente tick del
        // polling (como mucho medio segundo despues) vuelva a pedir el dato.
        handlerCorreccionGuardadaInput = function(e) {
            const grupoId = e.detail && e.detail.grupoId;
            const fechaStr = e.detail && e.detail.fechaStr; // 'YYYY-MM-DD'
            if (!grupoId || !fechaStr) return;
            const assetIdActual = localStorage.getItem('riego_asset_id');
            if (!assetIdActual || assetIdActual !== grupoId) return;
            if (!$ctx.timeWindow || !$ctx.timeWindow.minTime) return;
            const fechaMostrada = new Date($ctx.timeWindow.minTime);
            const fechaStrMostrada = fechaMostrada.getFullYear() + '-' +
                String(fechaMostrada.getMonth() + 1).padStart(2, '0') + '-' +
                String(fechaMostrada.getDate()).padStart(2, '0');
            if (fechaStrMostrada !== fechaStr) return;
            ultimoDiaPedido = null;
            cargarCaudalDelDia();
        };
        window.addEventListener('riego-correccion-guardada', handlerCorreccionGuardadaInput);
    }, 150);
};
// NUEVO: control de la peticion HTTP del valor real de "caudal_manual" del
// dia que se esta viendo -- evita relanzar la peticion cada segundo (el key
// de referencia es realtime) y descarta respuestas viejas si llegan
// DESPUES que una mas nueva (si no, pisaban el valor bueno con uno vacio).
var pollingIniciado = false;
var polling_intervalId = null;

function cargarCaudalDelDia() {
    const $ctx = self.ctx;
    if (!$ctx.timeWindow || !$ctx.timeWindow.minTime) {
        console.warn('[Guardar Caudal Manual] $ctx.timeWindow todavia no esta disponible -- no se puede saber que dia mostrar.');
        return;
    }
    const assetId = localStorage.getItem('riego_asset_id');
    if (!assetId || assetId === 'null') {
        console.warn('[Guardar Caudal Manual] No hay riego_asset_id en localStorage -- no se puede pedir el caudal manual de ningun dia.');
        return;
    }
    const fecha = new Date($ctx.timeWindow.minTime);
    const inicioDia = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), 0, 0, 0).getTime();
    const finDia = inicioDia + 86400000 - 1000;

    if (ultimoDiaPedido === inicioDia) return;
    ultimoDiaPedido = inicioDia;

    peticionActual++;
    const miPeticion = peticionActual;

    // IMPORTANTE: no basta con pedir "caudal_manual". En producción, este
    // hueco no salía vacío cuando no había manual -- mostraba el "caudal
    // medio" del día (el mismo que se ve en la celda de la tabla grande),
    // con la MISMA prioridad que usa esa tabla en procesarYpintar():
    //   1) caudal_manual, si existe (el usuario ya puso un valor manual ese día)
    //   2) si el día mostrado es HOY -> media_proyectada
    //   3) si no es hoy -> caudal_fijado
    //   4) si lo anterior no es un numero valido (>0) -> caudal_guarda, como ultimo recurso
    const now = new Date();
    const esHoy = (fecha.getFullYear() === now.getFullYear() &&
                   fecha.getMonth() === now.getMonth() &&
                   fecha.getDate() === now.getDate());

    const url = `/api/plugins/telemetry/ASSET/${assetId}/values/timeseries?keys=caudal_manual,caudal_fijado,media_proyectada,caudal_guarda&startTs=${inicioDia}&endTs=${finDia}&limit=200`;
    // --- DIAGNOSTICO: deja ver en la consola del navegador exactamente que
    // dia/ventana esta pidiendo este widget cada vez que cambia, y que
    // responde el servidor -- para saber si el problema es "no se entera
    // del cambio de dia" o "se entera bien pero el servidor no devuelve
    // el dato esperado".
    console.log('[Guardar Caudal Manual] timeWindow.minTime=' + $ctx.timeWindow.minTime +
        ' (' + fecha.toString() + ', esHoy=' + esHoy + ') -> pidiendo dia ' + new Date(inicioDia).toString());
    console.log('[Guardar Caudal Manual] URL: ' + url);
    $ctx.http.get(url).subscribe(function(data) {
        if (miPeticion !== peticionActual) return;
        console.log('[Guardar Caudal Manual] Respuesta para ese dia:', JSON.stringify(data));
        const $input = $ctx.$container.find('#input-caudal');

        function ultimoValor(arr) {
            if (!arr || arr.length === 0) return null;
            let mejor = arr[0];
            for (let i = 1; i < arr.length; i++) {
                if (arr[i].ts > mejor.ts) mejor = arr[i];
            }
            return mejor.value;
        }
        function esValido(v) {
            return v !== null && v !== undefined && v !== '' && !isNaN(parseFloat(v)) && parseFloat(v) > 0;
        }

        const manual = ultimoValor(data.caudal_manual);
        let valorAMostrar = null;
        if (esValido(manual)) {
            valorAMostrar = manual;
        } else {
            const principal = esHoy ? ultimoValor(data.media_proyectada) : ultimoValor(data.caudal_fijado);
            if (esValido(principal)) {
                valorAMostrar = principal;
            } else {
                const guarda = ultimoValor(data.caudal_guarda);
                if (esValido(guarda)) valorAMostrar = guarda;
            }
        }
        $input.val(valorAMostrar !== null ? Math.round(parseFloat(valorAMostrar)) : '');
    }, function(err) {
        // ANTES no habia manejador de error: si la peticion fallaba (permisos,
        // timing al abrir el dialogo, etc.) el campo se quedaba en blanco sin
        // ninguna pista de por que. Ahora se ve el error en consola y NO se
        // borra el campo (se deja lo que hubiera, en vez de vaciarlo a ciegas).
        if (miPeticion !== peticionActual) return;
        console.error('[Guardar Caudal Manual] Error al pedir caudal del dia ' + new Date(inicioDia).toString() + ':', err);
    });
}

self.onDataUpdated = function() {
    cargarCaudalDelDia();

    // Este widget no tiene datasource propio, asi que un cambio del
    // timeWindow del dashboard (flechas de dia anterior/siguiente) NO
    // dispara onDataUpdated por si solo. Se vigila con polling ligero
    // mientras el widget esta abierto, comparando minTime, para detectar
    // esos cambios igualmente y refrescar el input.
    if (!pollingIniciado) {
        pollingIniciado = true;
        polling_intervalId = setInterval(function() {
            cargarCaudalDelDia();
        }, 500);
    }
};

// IMPORTANTE: si el dialogo se cierra (o ThingsBoard destruye este widget)
// sin parar el setInterval, el polling se queda corriendo "en segundo
// plano" contra un $ctx/contenedor ya cerrado. Si luego se reabre el mismo
// estado, se arranca OTRO polling nuevo encima del viejo -- con dos (o
// mas) bucles compartiendo las mismas variables "ultimoDiaPedido" /
// "peticionActual", las respuestas se pisan entre si de forma
// impredecible y el campo puede quedarse sin actualizarse nunca. Se para
// aqui explicitamente para que cada apertura del dialogo parta de cero.
self.onDestroy = function() {
    if (polling_intervalId !== null) {
        clearInterval(polling_intervalId);
        polling_intervalId = null;
    }
    pollingIniciado = false;
    ultimoDiaPedido = null;
    if (handlerCorreccionGuardadaInput) {
        window.removeEventListener('riego-correccion-guardada', handlerCorreccionGuardadaInput);
        handlerCorreccionGuardadaInput = null;
    }
};
